// Some portions generated by Claude
import {
  memo,
  type CSSProperties,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
} from "react";
import { NODE_TEXT_LEFT } from "./graph-config.ts";
import { edgeLabelSize, graphNodePresentation, nodeCornerRadius } from "./graph-geometry.ts";
import { compactTerm } from "./graph-terms.ts";
import type { EdgeCurve, EdgeLabelPlacement, GraphEdge, GraphNode } from "./graph-types.ts";
import { nodeVisual, UNTYPED_IRI_TYPE } from "./graph-visuals.ts";
import { moreLinksPhrase } from "./link-counts.ts";
import { isApplePlatform } from "./graph-viewport.ts";
import { selectionKeys } from "./graph-selection.ts";

const SELECTION_KEYS = selectionKeys(isApplePlatform());

/**
 * Event handlers shared by every node. The object is created once and calls the explorer's current implementation,
 * so a node only re-renders when its own data or state changes, never because a handler was recreated.
 */
export type NodeHandlers = {
  click(nodeId: string, event: MouseEvent<SVGGElement>): void;
  doubleClick(nodeId: string, event: MouseEvent<SVGGElement>): void;
  hover(nodeId: string, entering: boolean): void;
  contextMenu(nodeId: string, event: MouseEvent<SVGGElement>): void;
  pointerDown(nodeId: string, event: PointerEvent<SVGGElement>): void;
  pointerMove(nodeId: string, event: PointerEvent<SVGGElement>): void;
  pointerEnd(event: PointerEvent<SVGGElement>, cancelled: boolean): void;
  keyDown(nodeId: string, event: KeyboardEvent<SVGGElement>): void;
  /** The node got the keyboard focus: it becomes the canvas's stop in the tab order. */
  focus(nodeId: string): void;
  /** The "+N" badge: load the node's next links. */
  more(nodeId: string): void;
};

export type NodeViewProps = {
  node: GraphNode;
  /** The hovered or focused node. */
  active: boolean;
  /** The active node or one of its neighbours. */
  related: boolean;
  selected: boolean;
  onPath: boolean;
  /** Selected or focused, for assistive technology. */
  pressed: boolean;
  dragging: boolean;
  expanding: boolean;
  /** Links in the repository that are not loaded yet ("+12", "920+"), or null. */
  more: string | null;
  /** The one node Tab reaches (the canvas is one stop; arrow keys move between nodes). */
  tabbable: boolean;
  handlers: NodeHandlers;
};

function typeLabelsOf(node: GraphNode) {
  if (node.kind === "literal") return "Literal";
  if (node.kind === "blank") return "Blank node";
  if (node.types === undefined) return "Type loading";
  return node.types.length ? node.types.map((type) => type.label).join(", ") : UNTYPED_IRI_TYPE.label;
}

function moreBadgeWidth(text: string) {
  return 12 + text.length * 6.5;
}

/** One node of the SVG canvas. Dimming comes from the canvas's state classes, not from props. */
export const NodeView = memo(function NodeView({
  node,
  active,
  related,
  selected,
  onPath,
  pressed,
  dragging,
  expanding,
  more,
  tabbable,
  handlers,
}: NodeViewProps) {
  if (node.x === undefined || node.y === undefined) return null;
  const { width, height, label } = graphNodePresentation(node);
  const visual = nodeVisual(node);
  const typeLabels = typeLabelsOf(node);
  const className =
    `graph-node ${node.kind}${active ? " is-focused" : ""}${related ? " is-related" : ""}${selected ? " is-selected" : ""}` +
    `${onPath ? " is-on-path" : ""}${node.pinned ? " is-pinned" : ""}${dragging ? " is-dragging" : ""}${expanding ? " is-expanding" : ""}`;
  return (
    <g
      className={className}
      transform={`translate(${node.x - width / 2} ${node.y - height / 2})`}
      style={{ "--node-color": visual.stroke, "--node-fill": visual.fill } as CSSProperties}
      tabIndex={tabbable ? 0 : -1}
      data-node-id={node.id}
      role="button"
      aria-pressed={pressed}
      aria-label={`${node.label}. ${typeLabels}.${more ? ` ${moreLinksPhrase(more)}.` : ""}${selected ? " Selected; dragging it moves the whole selection." : ""} Select to show its details; double-click to load its neighbours, or double-click and keep dragging to move it with its leaf neighbours. ${SELECTION_KEYS}click to add or remove it from the selection. Right-click or long-press for more actions. Arrow keys move to the next node in that direction; Delete hides it.`}
      onClick={(event) => handlers.click(node.id, event)}
      onDoubleClick={(event) => handlers.doubleClick(node.id, event)}
      onMouseEnter={() => handlers.hover(node.id, true)}
      onMouseLeave={() => handlers.hover(node.id, false)}
      onFocus={() => {
        handlers.hover(node.id, true);
        handlers.focus(node.id);
      }}
      onBlur={() => handlers.hover(node.id, false)}
      onContextMenu={(event) => handlers.contextMenu(node.id, event)}
      onPointerDown={(event) => handlers.pointerDown(node.id, event)}
      onPointerMove={(event) => handlers.pointerMove(node.id, event)}
      onPointerUp={(event) => handlers.pointerEnd(event, false)}
      onPointerCancel={(event) => handlers.pointerEnd(event, true)}
      onLostPointerCapture={(event) => handlers.pointerEnd(event, true)}
      onKeyDown={(event) => handlers.keyDown(node.id, event)}
    >
      <title>{`${node.label} · ${typeLabels}`}</title>
      <rect width={width} height={height} rx={nodeCornerRadius(node)} filter="url(#node-shadow)" />
      <circle cx="17" cy={height / 2} r="4" />
      <text x={NODE_TEXT_LEFT} y={height / 2 + 4}>
        {label}
      </text>
      {more ? (
        <g
          className="node-more"
          transform={`translate(${width} 0)`}
          onPointerDown={(event) => event.stopPropagation()}
          onDoubleClick={(event) => event.stopPropagation()}
          onClick={(event) => {
            event.stopPropagation();
            handlers.more(node.id);
          }}
        >
          <title>{`${moreLinksPhrase(more).replace(/^./, (first) => first.toUpperCase())}: click to load them`}</title>
          <rect x={-moreBadgeWidth(more) / 2} y={-9} width={moreBadgeWidth(more)} height={18} rx={9} />
          <text y={4}>{more}</text>
        </g>
      ) : null}
    </g>
  );
});

export type EdgeViewProps = {
  edge: GraphEdge;
  curve: EdgeCurve;
  sourceLabel: string;
  targetLabel: string;
  labelPlacement?: EdgeLabelPlacement;
  /** The edge touches the hovered or focused node. */
  touchesActive: boolean;
  /** The edge touches a selected node. */
  touchesSelection: boolean;
  onPath: boolean;
  selected: boolean;
};

/** One edge of the SVG canvas: its curve and its label when placed; `data-edge-id` lets the canvas pick it. */
export const EdgeView = memo(function EdgeView({
  edge,
  curve,
  sourceLabel,
  targetLabel,
  labelPlacement,
  touchesActive,
  touchesSelection,
  onPath,
  selected,
}: EdgeViewProps) {
  const labelSize = edgeLabelSize(edge);
  const className =
    `edge${edge.source === edge.target ? " is-self-loop" : ""}${touchesActive ? " touches-active" : ""}` +
    `${touchesSelection ? " touches-selection" : ""}${onPath ? " is-on-path" : ""}${labelPlacement ? " show-label" : ""}` +
    `${selected ? " is-selected" : ""}`;
  return (
    // The canvas picks edges on pointer-up (it captures the pointer, so a click here would land on the canvas).
    <g className={className} data-edge-id={edge.id}>
      <title>{`${sourceLabel} — ${edge.label} → ${targetLabel} (${compactTerm(edge.predicate, 32)})`}</title>
      <path d={curve.path} markerEnd="url(#arrow)" />
      {labelPlacement && (
        <>
          <line
            className="label-leader"
            x1={labelPlacement.anchor.x}
            y1={labelPlacement.anchor.y}
            x2={labelPlacement.point.x}
            y2={labelPlacement.point.y}
          />
          <rect
            x={labelPlacement.point.x - labelSize.width / 2}
            y={labelPlacement.point.y - labelSize.height / 2}
            width={labelSize.width}
            height={labelSize.height}
            rx="9"
          />
          <text x={labelPlacement.point.x} y={labelPlacement.point.y}>
            {labelSize.label}
          </text>
        </>
      )}
    </g>
  );
});

/**
 * Keeps an edge's curve object while its endpoints, bend and ports are unchanged, so memoized edges whose nodes did
 * not move skip rendering. Call with the previous cache; returns the curves and the next cache.
 */
export function stableCurves(
  next: ReadonlyMap<string, EdgeCurve>,
  previous: ReadonlyMap<string, EdgeCurve>,
): Map<string, EdgeCurve> {
  const result = new Map<string, EdgeCurve>();
  next.forEach((curve, id) => {
    const old = previous.get(id);
    result.set(id, old && old.path === curve.path ? old : curve);
  });
  return result;
}
